import MathFin.Foundations.IndepFreezing

open MeasureTheory ProbabilityTheory

/-- **The freezing lemma.** For independent `X` and `Y` and `g` integrable against the product
of their laws, `𝔼[g(X, Y)] = ∫ x, 𝔼[g(x, Y)] d(law X)`. -/
theorem freezing_lemma_thm {Ω α β : Type*} {mΩ : MeasurableSpace Ω} {mα : MeasurableSpace α}
    {mβ : MeasurableSpace β} {P : Measure Ω} [IsFiniteMeasure P] {X : Ω → α} {Y : Ω → β}
    (hXY : IndepFun X Y P) (hX : AEMeasurable X P) (hY : AEMeasurable Y P) {g : α × β → ℝ}
    (hg : Integrable g ((P.map X).prod (P.map Y))) :
    ∫ ω, g (X ω, Y ω) ∂P = ∫ x, ∫ ω, g (x, Y ω) ∂P ∂(P.map X) :=
  MathFin.integral_comp_prodMk_of_indepFun hXY hX hY hg
